SELECT CAST(result."id" AS VARCHAR) AS "id", CAST(result."phase_id" AS VARCHAR) AS "phase_id", CAST(result."championship_id" AS VARCHAR) AS "championship_id", CAST(result."round" AS INTEGER) AS "round", CAST(result."day" AS VARCHAR) AS "day", CAST(result."kickoff" AS VARCHAR) AS "kickoff", CAST(result."played" AS BOOLEAN) AS "played", CAST(result."home_id" AS VARCHAR) AS "home_id", CAST(result."away_id" AS VARCHAR) AS "away_id", CAST(result."home_name" AS VARCHAR) AS "home_name", CAST(result."away_name" AS VARCHAR) AS "away_name", CAST(result."home_score" AS INTEGER) AS "home_score", CAST(result."away_score" AS INTEGER) AS "away_score", CAST(result."home_aet" AS INTEGER) AS "home_aet", CAST(result."away_aet" AS INTEGER) AS "away_aet", CAST(result."home_pen" AS INTEGER) AS "home_pen", CAST(result."away_pen" AS INTEGER) AS "away_pen", CAST(result."championship_name" AS VARCHAR) AS "championship_name", CAST(result."phase_name" AS VARCHAR) AS "phase_name", CAST(result."stadium_id" AS VARCHAR) AS "stadium_id", CAST(result."stadium_name" AS VARCHAR) AS "stadium_name", CAST(result."referee_id" AS VARCHAR) AS "referee_id", CAST(result."referee_name" AS VARCHAR) AS "referee_name", CAST(result."attendance" AS INTEGER) AS "attendance" FROM (SELECT g.id,g.phase_id,p.championship_id,g."round",g.day,g.kickoff,g.played,g.home_id,g.away_id,
 h.name AS home_name,a.name AS away_name,g.home_score,g.away_score,g.home_aet,g.away_aet,g.home_pen,g.away_pen,
 c.full_name AS championship_name,p.name AS phase_name,g.stadium_id,s.name AS stadium_name,
 g.referee_id,r.name AS referee_name,g.attendance
 FROM source_game g JOIN source_phase p ON p.id=g.phase_id JOIN source_championship c ON c.id=p.championship_id
 JOIN source_team h ON h.id=g.home_id JOIN source_team a ON a.id=g.away_id
 LEFT JOIN source_stadium s ON s.id=g.stadium_id LEFT JOIN source_referee r ON r.id=g.referee_id) result;
